Read file src/components/SorteoApp.tsx, lines 1-236
1: "use client";
2: 
3: import { useState } from "react";
4: import ParticipantForm, {
5:   type Participante,
6: } from "@/components/ParticipantForm";
7: import ParticipantTable from "@/components/ParticipantTable";
8: import ConfiguracionSorteo, {
9:   esConfiguracionValida,
10:   type EstadoConfig,
11: } from "@/components/ConfiguracionSorteo";
12: import Exclusiones from "@/components/Exclusiones";
13: import SorteoButton from "@/components/SorteoButton";
14: import type { Exclusion } from "@/lib/sorteo";
15: 
16: type EstadoMensaje =
17:   | { tipo: "exito"; texto: string }
18:   | { tipo: "error"; texto: string }
19:   | null;
20: 
21: /** Clave canónica de un par de correos, sin distinguir mayúsculas/minúsculas. */
22: function clavePar(correo1: string, correo2: string): string {
23:   const a = correo1.toLowerCase();
24:   const b = correo2.toLowerCase();
25:   return a < b ? `${a}|${b}` : `${b}|${a}`;
26: }
27: 
28: /** Número válido (> 0) desde el texto crudo del formulario, o undefined. */
29: function aMonto(crudo: string): number | undefined {
30:   if (crudo.trim() === "") return undefined;
31:   const valor = Number(crudo);
32:   return Number.isFinite(valor) && valor > 0 ? valor : undefined;
33: }
34: 
35: /** Orquesta el flujo completo: agregar participantes → opciones → sortear. */
36: export default function SorteoApp() {
37:   const [participantes, setParticipantes] = useState<Participante[]>([]);
38:   const [config, setConfig] = useState<EstadoConfig>({
39:     tipo: "individual",
40:     cantidadAmigos: 2,
41:     montoMinimo: "",
42:     montoMaximo: "",
43:   });
44:   const [exclusiones, setExclusiones] = useState<Exclusion[]>([]);
45:   const [cargando, setCargando] = useState(false);
46:   const [mensaje, setMensaje] = useState<EstadoMensaje>(null);
47: 
48:   const configValida = esConfiguracionValida(config, participantes.length);
49: 
50:   function agregar(p: Participante): string | null {
51:     const duplicado = participantes.some(
52:       (x) => x.correo.toLowerCase() === p.correo.toLowerCase(),
53:     );
54:     if (duplicado) {
55:       return "Ese correo ya está registrado.";
56:     }
57:     setParticipantes((prev) => [...prev, p]);
58:     setMensaje(null);
59:     return null;
60:   }
61: 
62:   function eliminar(indice: number) {
63:     const eliminado = participantes[indice];
64:     setParticipantes((prev) => prev.filter((_, i) => i !== indice));
65:     // Las exclusiones que citaban al eliminado ya no tienen sentido.
66:     if (eliminado) {
67:       setExclusiones((prev) =>
68:         prev.filter(
69:           (e) =>
70:             e.correo1.toLowerCase() !== eliminado.correo.toLowerCase() &&
71:             e.correo2.toLowerCase() !== eliminado.correo.toLowerCase(),
72:         ),
73:       );
74:     }
75:     setMensaje(null);
76:   }
77: 
78:   function actualizarConfig(actualizacion: Partial<EstadoConfig>) {
79:     setConfig((prev) => ({ ...prev, ...actualizacion }));
80:     setMensaje(null);
81:   }
82: 
83:   function agregarExclusion(correo1: string, correo2: string): string | null {
84:     if (correo1.toLowerCase() === correo2.toLowerCase()) {
85:       return "No se puede excluir a un participante consigo mismo.";
86:     }
87:     const clave = clavePar(correo1, correo2);
88:     if (exclusiones.some((e) => clavePar(e.correo1, e.correo2) === clave)) {
89:       return "Esa exclusión ya está definida.";
90:     }
91:     setExclusiones((prev) => [...prev, { correo1, correo2 }]);
92:     setMensaje(null);
93:     return null;
94:   }
95: 
96:   function eliminarExclusion(indice: number) {
97:     setExclusiones((prev) => prev.filter((_, i) => i !== indice));
98:     setMensaje(null);
99:   }
100: 
101:   /** Arma el objeto `opciones` solo con las elecciones definidas. */
102:   function construirOpciones() {
103:     const minimo = aMonto(config.montoMinimo);
104:     const maximo = aMonto(config.montoMaximo);
105:     const opciones: Record<string, unknown> = {
106:       tipo: config.tipo,
107:       exclusiones,
108:     };
109:     if (config.tipo === "multiple") {
110:       opciones.cantidadAmigos = config.cantidadAmigos;
111:     }
112:     if (minimo !== undefined || maximo !== undefined) {
113:       opciones.montoSugerido = {
114:         ...(minimo !== undefined ? { minimo } : {}),
115:         ...(maximo !== undefined ? { maximo } : {}),
116:       };
117:     }
118:     return opciones;
119:   }
120: 
121:   async function lanzarSorteo() {
122:     setCargando(true);
123:     setMensaje(null);
124:     try {
125:       const respuesta = await fetch("/api/sorteo", {
126:         method: "POST",
127:         headers: { "Content-Type": "application/json" },
128:         body: JSON.stringify({ participantes, opciones: construirOpciones() }),
129:       });
130:       const cuerpo = await respuesta.json();
131: 
132:       if (!respuesta.ok) {
133:         setMensaje({
134:           tipo: "error",
135:           texto: cuerpo.error ?? "Ocurrió un error inesperado.",
136:         });
137:       } else {
138:         setMensaje({
139:           tipo: "exito",
140:           texto: `¡Sorteo realizado! Se enviaron ${cuerpo.enviados} correos con las asignaciones.`,
141:         });
142:         setParticipantes([]);
143:         setExclusiones([]);
144:       }
145:     } catch {
146:       setMensaje({
147:         tipo: "error",
148:         texto: "No se pudo contactar al servidor. Vuelve a intentarlo.",
149:       });
150:     } finally {
151:       setCargando(false);
152:     }
153:   }
154: 
155:   return (
156:     <div className="space-y-8">
157:       <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
158:         <h2 className="mb-4 text-lg font-semibold">1. Agrega participantes</h2>
159:         <ParticipantForm alAgregar={agregar} />
160:       </section>
161: 
162:       <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
163:         <h2 className="mb-4 text-lg font-semibold">2. Lista de participantes</h2>
164:         <ParticipantTable participantes={participantes} alEliminar={eliminar} />
165:       </section>
166: 
167:       <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
168:         <h2 className="mb-4 text-lg font-semibold">3. Exclusiones (opcional)</h2>
169:         <p className="mb-4 text-sm text-zinc-500">
170:           Define parejas que no pueden tocarse entre sí (parejas, familiares
171:           directos, etc.). La exclusión vale en ambas direcciones del regalo.
172:         </p>
173:         <Exclusiones
174:           participantes={participantes}
175:           exclusiones={exclusiones}
176:           alAgregar={agregarExclusion}
177:           alEliminar={eliminarExclusion}
178:         />
179:       </section>
180: 
181:       <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
182:         <h2 className="mb-4 text-lg font-semibold">
183:           4. Configuración del sorteo
184:         </h2>
185:         <ConfiguracionSorteo
186:           config={config}
187:           numParticipantes={participantes.length}
188:           alActualizar={actualizarConfig}
189:         />
190:       </section>
191: 
192:       <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
193:         <h2 className="mb-4 text-lg font-semibold">5. Sorteo</h2>
194:         <div className="flex flex-wrap items-center gap-4">
195:           <SorteoButton
196:             deshabilitado={!configValida}
197:             cargando={cargando}
198:             alLanzar={lanzarSorteo}
199:           />
200:           {participantes.length < 2 && (
201:             <span className="text-sm text-zinc-500">
202:               Se necesitan al menos 2 participantes para sortear.
203:             </span>
204:           )}
205:           {participantes.length >= 2 && !configValida && (
206:             <span className="text-sm text-red-600">
207:               Revisa la configuración: hay opciones incompletas o sin sentido
208:               con la lista de participantes actual.
209:             </span>
210:           )}
211:         </div>
212:         <p className="mt-3 text-sm text-zinc-500">
213:           {config.tipo === "multiple" && configValida
214:             ? `Cada persona regalará y recibirá exactamente ${config.cantidadAmigos} regalos, a personas distintas y sin repetir parejas.`
215:             : "Nadie recibirá su propio nombre y cada persona regalará y recibirá exactamente una vez."}{" "}
216:           Si definiste exclusiones, el sorteo las respeta; si con ellas no
217:           existe reparto posible, la API lo avisará sin enviar nada. Cada
218:           participante recibirá su asignación por correo, mostrando únicamente
219:           a quién le toca regalar.
220:         </p>
221:         {mensaje && (
222:           <p
223:             aria-live="polite"
224:             className={
225:               mensaje.tipo === "exito"
226:                 ? "mt-4 rounded-md bg-emerald-50 px-4 py-2 text-sm text-emerald-700"
227:                 : "mt-4 rounded-md bg-red-50 px-4 py-2 text-sm text-red-700"
228:             }
229:           >
230:             {mensaje.texto}
231:           </p>
232:         )}
233:       </section>
234:     </div>
235:   );
236: }

