Read file src/components/ConfiguracionSorteo.tsx, lines 1-192
1: "use client";
2: 
3: /** Tipo de sorteo: "individual" (clásico) o "multiple" (varios amigos secretos). */
4: export type TipoSorteo = "individual" | "multiple";
5: 
6: /** Estado de la configuración editable por el organizador. */
7: export interface EstadoConfig {
8:   tipo: TipoSorteo;
9:   /** Cantidad de amigos secretos por participante (solo si tipo es múltiple). */
10:   cantidadAmigos: number;
11:   /** Textos crudos de los campos de monto; "" significa sin definir. */
12:   montoMinimo: string;
13:   montoMaximo: string;
14: }
15: 
16: export const CONFIG_INICIAL: EstadoConfig = {
17:   tipo: "individual",
18:   cantidadAmigos: 2,
19:   montoMinimo: "",
20:   montoMaximo: "",
21: };
22: 
23: interface Props {
24:   config: EstadoConfig;
25:   numParticipantes: number;
26:   alActualizar: (actualizacion: Partial<EstadoConfig>) => void;
27: }
28: 
29: /** Numero positivo o NaN/negativo si el texto no es un monto válido. */
30: function aNumero(crudo: string): number {
31:   if (crudo.trim() === "") return NaN;
32:   const valor = Number(crudo);
33:   return Number.isFinite(valor) ? valor : NaN;
34: }
35: 
36: /** Indica si el texto es vacío o un monto positivo válido. */
37: function montoValido(crudo: string): boolean {
38:   return crudo.trim() === "" || aNumero(crudo) > 0;
39: }
40: 
41: /**
42:  * La configuración permite sortear: participantes suficientes, cantidad de
43:  * amigos secretos en rango y montos numéricamente coherentes.
44:  */
45: export function esConfiguracionValida(
46:   config: EstadoConfig,
47:   numParticipantes: number,
48: ): boolean {
49:   if (numParticipantes < 2) return false;
50:   if (config.tipo === "multiple") {
51:     const maxima = numParticipantes - 1;
52:     if (
53:       !Number.isInteger(config.cantidadAmigos) ||
54:       config.cantidadAmigos < 2 ||
55:       config.cantidadAmigos > maxima
56:     ) {
57:       return false;
58:     }
59:   }
60:   if (!montoValido(config.montoMinimo) || !montoValido(config.montoMaximo)) {
61:     return false;
62:   }
63:   const minimo = aNumero(config.montoMinimo);
64:   const maximo = aNumero(config.montoMaximo);
65:   if (Number.isFinite(minimo) && Number.isFinite(maximo) && minimo > maximo) {
66:     return false;
67:   }
68:   return true;
69: }
70: 
71: /** Sección de configuración: tipo de sorteo, cantidad y monto sugerido. */
72: export default function ConfiguracionSorteo({
73:   config,
74:   numParticipantes,
75:   alActualizar,
76: }: Props) {
77:   const esMultiple = config.tipo === "multiple";
78:   const maximaCantidad = numParticipantes - 1;
79:   const cantidadInvalida =
80:     esMultiple &&
81:     (config.cantidadAmigos < 2 || config.cantidadAmigos > maximaCantidad);
82: 
83:   return (
84:     <div className="space-y-4">
85:       <fieldset>
86:         <legend className="text-sm font-medium text-zinc-700">
87:           Tipo de sorteo
88:         </legend>
89:         <div className="mt-2 flex flex-col gap-2 sm:flex-row sm:gap-6">
90:           <label className="flex items-center gap-2 text-sm">
91:             <input
92:               type="radio"
93:               name="tipo-sorteo"
94:               value="individual"
95:               checked={config.tipo === "individual"}
96:               onChange={() => alActualizar({ tipo: "individual" })}
97:             />
98:             Individual (clásico): una persona, un regalo
99:           </label>
100:           <label className="flex items-center gap-2 text-sm">
101:             <input
102:               type="radio"
103:               name="tipo-sorteo"
104:               value="multiple"
105:               checked={config.tipo === "multiple"}
106:               onChange={() => alActualizar({ tipo: "multiple" })}
107:             />
108:             Multiple: cada quien regala a varias personas
109:           </label>
110:         </div>
111:       </fieldset>
112: 
113:       {esMultiple && (
114:         <div>
115:           <label
116:             htmlFor="cantidad-amigos"
117:             className="block text-sm font-medium text-zinc-700"
118:           >
119:             Cantidad de amigos secretos por participante
120:           </label>
121:           <input
122:             id="cantidad-amigos"
123:             type="number"
124:             min={2}
125:             max={maximaCantidad > 1 ? maximaCantidad : 2}
126:             value={config.cantidadAmigos}
127:             onChange={(e) =>
128:               alActualizar({ cantidadAmigos: Number(e.target.value) })
129:             }
130:             className="mt-1 w-40 rounded-md border border-zinc-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
131:           />
132:           {cantidadInvalida && (
133:             <p aria-live="polite" className="mt-1 text-sm text-red-600">
134:               La cantidad debe estar entre 2 y la cantidad de participantes
135:               menos uno (hoy: {Math.max(maximaCantidad, 2)}).
136:             </p>
137:           )}
138:         </div>
139:       )}
140: 
141:       <fieldset>
142:         <legend className="text-sm font-medium text-zinc-700">
143:           Monto sugerido del regalo (opcional)
144:         </legend>
145:         <p className="mt-1 text-xs text-zinc-500">
146:           Puedes definir solo un mínimo, o un mínimo y un máximo como rango.
147:         </p>
148:         <div className="mt-2 flex flex-wrap items-center gap-2">
149:           <label className="text-sm text-zinc-600">
150:             Mínimo
151:             <input
152:               type="number"
153:               min={0}
154:               step="0.01"
155:               aria-label="Monto mínimo sugerido"
156:               value={config.montoMinimo}
157:               onChange={(e) => alActualizar({ montoMinimo: e.target.value })}
158:               className="ml-2 w-32 rounded-md border border-zinc-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
159:             />
160:           </label>
161:           <label className="text-sm text-zinc-600">
162:             Máximo
163:             <input
164:               type="number"
165:               min={0}
166:               step="0.01"
167:               aria-label="Monto máximo sugerido"
168:               value={config.montoMaximo}
169:               onChange={(e) => alActualizar({ montoMaximo: e.target.value })}
170:               className="ml-2 w-32 rounded-md border border-zinc-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
171:             />
172:           </label>
173:         </div>
174:         {(!montoValido(config.montoMinimo) || !montoValido(config.montoMaximo)) && (
175:           <p aria-live="polite" className="mt-1 text-sm text-red-600">
176:             Los montos deben ser números mayores que cero.
177:           </p>
178:         )}
179:         {!cantidadInvalida &&
180:           montoValido(config.montoMinimo) &&
181:           montoValido(config.montoMaximo) &&
182:           aNumero(config.montoMinimo) > aNumero(config.montoMaximo) &&
183:           config.montoMinimo.trim() !== "" &&
184:           config.montoMaximo.trim() !== "" && (
185:             <p aria-live="polite" className="mt-1 text-sm text-red-600">
186:               El monto máximo no puede ser menor que el mínimo.
187:             </p>
188:           )}
189:       </fieldset>
190:     </div>
191:   );
192: }

