import type { ButtonHTMLAttributes } from "react";

type VarianteBoton = "primario" | "secundario" | "fantasma-peligro";
type TamanoBoton = "normal" | "grande";

interface Props extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** primario: acción principal; secundario: acciones de apoyo;
   *  fantasma-peligro: acciones destructivas sin fondo. */
  variante?: VarianteBoton;
  tamaño?: TamanoBoton;
}

const CLASES_VARIANTE: Record<VarianteBoton, string> = {
  primario:
    "bg-primario text-sobre-primario shadow-sm hover:bg-primario-hover disabled:border disabled:border-borde disabled:bg-superficie-suave disabled:text-texto-suave disabled:shadow-none",
  secundario:
    "border border-borde-fuerte bg-superficie text-primario hover:bg-superficie-suave disabled:border-borde disabled:bg-superficie-suave disabled:text-texto-suave",
  "fantasma-peligro":
    "text-peligro hover:bg-peligro-fondo disabled:text-texto-suave disabled:hover:bg-transparent",
};

const CLASES_TAMANO: Record<TamanoBoton, string> = {
  normal: "px-4 py-2 text-sm",
  grande: "px-6 py-3 text-base",
};

/**
 * Botón con variantes tokenizadas: colores semánticos, estados de hover,
 * deshabilitado y foco visibles en ambos temas.
 */
export default function Boton({
  variante = "primario",
  tamaño = "normal",
  className = "",
  type = "button",
  ...resto
}: Props) {
  return (
    <button
      type={type}
      className={`inline-flex cursor-pointer items-center justify-center gap-2 rounded-control font-semibold transition-colors duration-200 outline-none focus-visible:ring-2 focus-visible:ring-foco focus-visible:ring-offset-2 focus-visible:ring-offset-fondo disabled:cursor-not-allowed ${CLASES_VARIANTE[variante]} ${CLASES_TAMANO[tamaño]} ${className}`}
      {...resto}
    />
  );
}

import type { InputHTMLAttributes, Ref } from "react";

interface Props extends Omit<InputHTMLAttributes<HTMLInputElement>, "id"> {
  id: string;
  /** Etiqueta visible del campo. */
  etiqueta: string;
  /** Mensaje de error del campo; se anuncia con el input vía aria-describedby. */
  error?: string | null;
  className?: string;
}

/**
 * Campo de texto con etiqueta visible y error conectado por `aria-describedby`.
 * En React 19 el `ref` llega como prop normal y se aplica al input.
 */
export default function Campo({
  id,
  etiqueta,
  error = null,
  className = "",
  ref,
  ...resto
}: Props & { ref?: Ref<HTMLInputElement> }) {
  const idError = `${id}-error`;
  return (
    <div className={className}>
      <label
        htmlFor={id}
        className="mb-1 block text-sm font-medium text-texto"
      >
        {etiqueta}
      </label>
      <input
        id={id}
        ref={ref}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? idError : undefined}
        className={`w-full rounded-control border bg-superficie px-3 py-2 text-sm text-texto outline-none transition-shadow duration-150 placeholder:text-texto-suave/70 focus:ring-2 focus:ring-foco/40 ${
          error
            ? "border-peligro"
            : "border-borde-fuerte focus:border-acentuado"
        }`}
        {...resto}
      />
      {error && (
        <p id={idError} className="mt-1 text-sm text-peligro">
          {error}
        </p>
      )}
    </div>
  );
}

"use client";

import { IconoLuna, IconoSol } from "@/components/iconos";

/**
 * Alternador de tema claro/oscuro. Opera sobre la clase `dark` en <html> y
 * persiste la elección en localStorage; el valor inicial lo aplica un script
 * temprano en el layout (también respeta `prefers-color-scheme` la primera vez).
 * Los dos iconos se muestran/ocultan por CSS según el tema activo, así el
 * componente no depende de estado de React ni sufre desajuste de hidratación.
 */
export default function AlternarTema() {
  function alternar() {
    const oscuro = document.documentElement.classList.toggle("dark");
    try {
      localStorage.setItem("tema", oscuro ? "oscuro" : "claro");
    } catch {
      // Sin almacenamiento disponible: el tema solo cambia en esta visita.
    }
  }

  return (
    <button
      type="button"
      onClick={alternar}
      aria-label="Cambiar entre modo claro y oscuro"
      className="flex h-10 w-10 cursor-pointer items-center justify-center rounded-control border border-borde bg-superficie text-texto-suave transition-colors duration-200 hover:bg-superficie-suave hover:text-texto outline-none focus-visible:ring-2 focus-visible:ring-foco focus-visible:ring-offset-2 focus-visible:ring-offset-fondo"
    >
      {/* Luna visible en claro (cambia a oscuro), sol visible en oscuro. */}
      <IconoLuna className="h-5 w-5 dark:hidden" />
      <IconoSol className="hidden h-5 w-5 dark:block" />
    </button>
  );
}

